{% extends 'base.html' %}

{% block title %}Kanban Board - {{ project.name }}{% endblock %}

{% block extra_head %}
<style>
    .kanban-board {
        display: flex;
        gap: 1rem;
        overflow-x: auto;
        padding-bottom: 1rem;
    }
    .kanban-lane {
        flex: 1;
        min-width: 280px;
        background-color: #f4f5f7;
        border-radius: 3px;
        padding: 0.5rem;
    }
    .kanban-lane h5 {
        margin-bottom: 1rem;
        padding-bottom: 0.5rem;
        border-bottom: 1px solid #ccc;
    }
    .kanban-card {
        background-color: #fff;
        border-radius: 3px;
        padding: 1rem;
        margin-bottom: 0.5rem;
        box-shadow: 0 1px 0 rgba(9,30,66,.25);
        cursor: grab;
    }
    .kanban-card:hover {
        background-color: #f8f9fa;
    }
    .dragging {
        opacity: 0.5;
    }
</style>
{% endblock %}

{% block content %}
    <div class="d-flex justify-content-between align-items-center mb-4">
        <h1>Kanban Board: {{ project.name }}</h1>
        <a href="{% url 'management:project-detail' project.pk %}" class="btn btn-secondary">Back to Detail View</a>
    </div>

    <div class="kanban-board">
        {% for status_key, status_label in status_choices %}
        <div class="kanban-lane" data-status="{{ status_key }}">
            <h5>{{ status_label }}</h5>
            <div class="kanban-tasks">
                {% for task in status_lanes|get_item:status_key %}
                <div class="kanban-card" draggable="true" data-task-id="{{ task.id }}">
                    <h6>{{ task.name }}</h6>
                    <p><small>Due: {{ task.end_date }}</small></p>
                </div>
                {% endfor %}
            </div>
        </div>
        {% endfor %}
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const cards = document.querySelectorAll('.kanban-card');
            const lanes = document.querySelectorAll('.kanban-lane');

            cards.forEach(card => {
                card.addEventListener('dragstart', () => {
                    card.classList.add('dragging');
                });

                card.addEventListener('dragend', () => {
                    card.classList.remove('dragging');
                });
            });

            lanes.forEach(lane => {
                lane.addEventListener('dragover', e => {
                    e.preventDefault();
                    const afterElement = getDragAfterElement(lane, e.clientY);
                    const draggable = document.querySelector('.dragging');
                    const taskContainer = lane.querySelector('.kanban-tasks');
                    if (afterElement == null) {
                        taskContainer.appendChild(draggable);
                    } else {
                        taskContainer.insertBefore(draggable, afterElement);
                    }
                });

                lane.addEventListener('drop', e => {
                    e.preventDefault();
                    const draggable = document.querySelector('.dragging');
                    const newStatus = lane.dataset.status;
                    const taskId = draggable.dataset.taskId;

                    // Optimistically update UI
                    const taskContainer = lane.querySelector('.kanban-tasks');
                    taskContainer.appendChild(draggable);

                    // Send request to server
                    fetch(`{% url 'management:update-task-status' %}`,
                    {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                            'X-CSRFToken': '{{ csrf_token }}'
                        },
                        body: JSON.stringify({ task_id: taskId, new_status: newStatus })
                    })
                    .then(response => response.json())
                    .then(data => {
                        if (!data.success) {
                            // Revert on failure
                            console.error('Failed to update task status');
                            // A more robust solution would be to move the card back to its original lane
                        }
                    });
                });
            });

            function getDragAfterElement(lane, y) {
                const draggableElements = [...lane.querySelectorAll('.kanban-card:not(.dragging)')];

                return draggableElements.reduce((closest, child) => {
                    const box = child.getBoundingClientRect();
                    const offset = y - box.top - box.height / 2;
                    if (offset < 0 && offset > closest.offset) {
                        return { offset: offset, element: child };
                    } else {
                        return closest;
                    }
                }, { offset: Number.NEGATIVE_INFINITY }).element;
            }
        });
    </script>
{% endblock %}

