def create_gantt_chart(project):
    tasks_with_levels = get_all_tasks(project)
    if not tasks_with_levels:
        return None

    critical_path_ids, slack_days = calculate_schedule_metrics(project)

    df_data = []
    baseline_data = {item['id']: item for item in project.active_baseline.data} if project.active_baseline else {}

    for item in tasks_with_levels:
        task = item['task']
        level = item['level']
        is_summary = task.subtasks.exists()

        start_date = task.start_date
        end_date = task.end_date
        if is_summary:
            descendants = []
            def get_all_descendants(t):
                for sub_task in t.subtasks.all():
                    descendants.append(sub_task)
                    get_all_descendants(sub_task)
            get_all_descendants(task)
            if descendants:
                start_date = min(d.start_date for d in descendants)
                end_date = max(d.end_date for d in descendants)

        wbs_number = item['wbs']
        full_label = f"{wbs_number} {task.name}"
        indent = '&nbsp;' * 6 * level

        baseline_task = baseline_data.get(task.id)

        df_data.append({
            'Task': indent + full_label,
            'Start': start_date,
            'Finish': end_date,
            'id': task.id,
            'is_summary': is_summary,
            'is_milestone': (end_date - start_date).days == 0 and not is_summary,
            'is_critical': task.id in critical_path_ids,
            'slack': slack_days.get(task.id, 0),
            'progress': task.progress,
            'status': task.status,
            'status_label': task.get_status_display(),
            'baseline_start': pd.to_datetime(baseline_task['start_date']) if baseline_task else None,
            'baseline_finish': pd.to_datetime(baseline_task['end_date']) if baseline_task else None,
        })

    df = pd.DataFrame(df_data)
    y_axis_labels = df['Task'].tolist()

    fig = go.Figure()

    # Add baseline bars
    baseline_df = df.dropna(subset=['baseline_start', 'baseline_finish'])
    if not baseline_df.empty:
        fig.add_trace(go.Bar(
            y=baseline_df['Task'],
            x=(baseline_df['baseline_finish'] - baseline_df['baseline_start']).dt.total_seconds() * 1000,
            base=baseline_df['baseline_start'],
            orientation='h',
            marker_color='#d3d3d3',
            name='Baseline',
            hoverinfo='none'
        ))

    status_colors = {
        'NS': {'bg': '#e0e0e0', 'fg': '#616161'}, # Not Started
        'IP': {'bg': '#bbdefb', 'fg': '#1976d2'}, # In Progress
        'CO': {'bg': '#a5d6a7', 'fg': '#388e3c'}, # Completed
        'OH': {'bg': '#ffecb3', 'fg': '#f57c00'}, # On Hold
        'CA': {'bg': '#ffcdd2', 'fg': '#d32f2f'}, # Cancelled
    }

    # Group tasks by status for legend
    task_df = df[~df['is_summary'] & ~df['is_milestone']]
    for status_code, status_label in StatusChoices.choices:
        status_df = task_df[task_df['status'] == status_code]
        if status_df.empty:
            continue

        # Background bars
        fig.add_trace(go.Bar(
            y=status_df['Task'], x=[(r.Finish - r.Start).total_seconds() * 1000 for r in status_df.itertuples()],
            base=status_df['Start'], orientation='h', marker_color=status_colors[status_code]['bg'],
            name=status_label, showlegend=True, hoverinfo='none'
        ))

        # Manually create customdata for hovertemplate
        custom_data = []
        for row in status_df.itertuples():
            custom_data.append([
                row.progress,
                row.Start.strftime('%Y-%m-%d'),
                row.Finish.strftime('%Y-%m-%d'),
                row.slack
            ])

        # Progress bars
        fig.add_trace(go.Bar(
            y=status_df['Task'], 
            x=[((r.Finish - r.Start).total_seconds() * 1000) * (float(r.progress) / 100.0) for r in status_df.itertuples()],
            base=status_df['Start'], orientation='h', marker_color=status_colors[status_code]['fg'],
            showlegend=False, name=f'Progress',
            hovertemplate=(
                "<b>%{y}</b><br>" +
                f"Status: {status_label}<br>" +
                "Progress: %{customdata[0]}%<br>" +
                "Start: %{customdata[1]}<br>" +
                "Finish: %{customdata[2]}<br>" +
                "Slack: %{customdata[3]} days<extra></extra>"
            ),
            customdata=custom_data
        ))

    # Add Summary and Milestone traces
    summary_df = df[df['is_summary']]
    if not summary_df.empty:
        fig.add_trace(go.Scatter(
            x=summary_df['Start'], y=summary_df['Task'], mode='markers',
            marker=dict(symbol='diamond', color='black', size=10), name='Summary Task'
        ))

    milestone_df = df[df['is_milestone']]
    if not milestone_df.empty:
        fig.add_trace(go.Scatter(
            x=milestone_df['Start'], y=milestone_df['Task'], mode='markers',
            marker=dict(symbol='diamond', color='#f57c00', size=12), name='Milestone'
        ))

    # Add dependency arrows
    arrows = []
    task_y_mapping = {label: i for i, label in enumerate(y_axis_labels)}
