    in_degree = {t.id: t.predecessors.count() for t in tasks}
    queue = [t.id for t in tasks if in_degree[t.id] == 0]
    while queue:
        task_id = queue.pop(0)
        sorted_tasks.append(task_id)
        for dependent_task_id in adj[task_id]:
            in_degree[dependent_task_id] -= 1
            if in_degree[dependent_task_id] == 0:
                queue.append(dependent_task_id)

    for task_id in sorted_tasks:
        task = task_map[task_id]
        duration = (task.end_date - task.start_date).days + 1
        max_pred_ef = 0
        for dep in task.predecessors.all():
            pred_task = dep.predecessor
            pred_duration = (pred_task.end_date - pred_task.start_date).days + 1
            if dep.type == 'FS':
                max_pred_ef = max(max_pred_ef, es[pred_task.id] + pred_duration)
            elif dep.type == 'SS':
                max_pred_ef = max(max_pred_ef, es[pred_task.id])
            elif dep.type == 'FF':
                max_pred_ef = max(max_pred_ef, es[pred_task.id] + pred_duration - duration)
            elif dep.type == 'SF':
                max_pred_ef = max(max_pred_ef, es[pred_task.id] - duration)
        es[task_id] = max_pred_ef + 1

    ef = {t_id: es[t_id] + ((task_map[t_id].end_date - task_map[t_id].start_date).days) for t_id in es}

    project_finish_time = max(ef.values()) if ef else 0

    # Calculate Latest Start (LS) and Latest Finish (LF)
    lf = {task.id: project_finish_time for task in tasks}
    ls = {t_id: lf[t_id] - ((task_map[t_id].end_date - task_map[t_id].start_date).days) for t_id in lf}

    for task_id in reversed(sorted_tasks):
        for succ_dep in task_map[task_id].successors.all():
            succ_task = succ_dep.successor
            succ_duration = (succ_task.end_date - succ_task.start_date).days + 1
            if succ_dep.type == 'FS':
                lf[task_id] = min(lf[task_id], ls[succ_task.id] - 1)
            elif succ_dep.type == 'SS':
                ls[task_id] = min(ls[task_id], ls[succ_task.id])
            elif succ_dep.type == 'FF':
                lf[task_id] = min(lf[task_id], lf[succ_task.id])
            elif succ_dep.type == 'SF':
                ls[task_id] = min(ls[task_id], lf[succ_task.id] - succ_duration)
            ls[task_id] = lf[task_id] - duration + 1

    # Calculate Slack and Critical Path
    slack = {t_id: ls[t_id] - es[t_id] for t_id in es}
    critical_path_ids = {t_id for t_id, s in slack.items() if s == 0}

    return critical_path_ids, slack

def create_gantt_chart(project):
    tasks_with_levels = get_all_tasks(project)
    if not tasks_with_levels:
        return None

    critical_path_ids, slack_days = calculate_schedule_metrics(project)

    df_data = []
    baseline_data = {item['id']: item for item in project.active_baseline.data} if project.active_baseline else {}

    for item in tasks_with_levels:
        task = item['task']
        level = item['level']
        is_summary = task.subtasks.exists()

        start_date = task.start_date
        end_date = task.end_date
        if is_summary:
            descendants = []
            def get_all_descendants(t):
                for sub_task in t.subtasks.all():
                    descendants.append(sub_task)
                    get_all_descendants(sub_task)
            get_all_descendants(task)
            if descendants:
                start_date = min(d.start_date for d in descendants)
                end_date = max(d.end_date for d in descendants)

        wbs_number = item['wbs']
        full_label = f"{wbs_number} {task.name}"
        indent = '&nbsp;' * 6 * level

        baseline_task = baseline_data.get(task.id)

        df_data.append({
            'Task': indent + full_label,
            'Start': start_date,
            'Finish': end_date,
            'id': task.id,
            'is_summary': is_summary,
            'is_milestone': (end_date - start_date).days == 0 and not is_summary,
            'is_critical': task.id in critical_path_ids,
            'slack': slack_days.get(task.id, 0),
            'progress': task.progress,
            'status': task.status,
            'status_label': task.get_status_display(),
            'baseline_start': pd.to_datetime(baseline_task['start_date']) if baseline_task else None,
            'baseline_finish': pd.to_datetime(baseline_task['end_date']) if baseline_task else None,
        })

    df = pd.DataFrame(df_data)
    y_axis_labels = df['Task'].tolist()

    fig = go.Figure()

    # Add baseline bars
    baseline_df = df.dropna(subset=['baseline_start', 'baseline_finish'])
    if not baseline_df.empty:
        fig.add_trace(go.Bar(
            y=baseline_df['Task'],
            x=(baseline_df['baseline_finish'] - baseline_df['baseline_start']).dt.total_seconds() * 1000,
            base=baseline_df['baseline_start'],
            orientation='h',
            marker_color='#d3d3d3',
            name='Baseline',
            hoverinfo='none'
        ))

    status_colors = {
        'NS': {'bg': '#e0e0e0', 'fg': '#616161'}, # Not Started
        'IP': {'bg': '#bbdefb', 'fg': '#1976d2'}, # In Progress
        'CO': {'bg': '#a5d6a7', 'fg': '#388e3c'}, # Completed
        'OH': {'bg': '#ffecb3', 'fg': '#f57c00'}, # On Hold
        'CA': {'bg': '#ffcdd2', 'fg': '#d32f2f'}, # Cancelled
    }

    # Group tasks by status for legend
    task_df = df[~df['is_summary'] & ~df['is_milestone']]
    for status_code, status_label in StatusChoices.choices:
        status_df = task_df[task_df['status'] == status_code]
        if status_df.empty:
            continue

        # Background bars
        fig.add_trace(go.Bar(
            y=status_df['Task'], x=[(r.Finish - r.Start).total_seconds() * 1000 for r in status_df.itertuples()],
            base=status_df['Start'], orientation='h', marker_color=status_colors[status_code]['bg'],
            name=status_label, showlegend=True, hoverinfo='none'
        ))

        # Manually create customdata for hovertemplate
        custom_data = []
        for row in status_df.itertuples():
            custom_data.append([
                row.progress,
                row.Start.strftime('%Y-%m-%d'),
                row.Finish.strftime('%Y-%m-%d'),
                row.slack
            ])

        # Progress bars
        fig.add_trace(go.Bar(
            y=status_df['Task'], 
            x=[((r.Finish - r.Start).total_seconds() * 1000) * (float(r.progress) / 100.0) for r in status_df.itertuples()],
            base=status_df['Start'], orientation='h', marker_color=status_colors[status_code]['fg'],
            showlegend=False, name=f'Progress',
            hovertemplate=(
                "<b>%{y}</b><br>" +
                f"Status: {status_label}<br>" +
                "Progress: %{customdata[0]}%<br>" +
                "Start: %{customdata[1]}<br>" +
                "Finish: %{customdata[2]}<br>" +
                "Slack: %{customdata[3]} days<extra></extra>"
            ),
            customdata=custom_data
        ))

    # Add Summary and Milestone traces
    summary_df = df[df['is_summary']]
    if not summary_df.empty:
        fig.add_trace(go.Scatter(
            x=summary_df['Start'], y=summary_df['Task'], mode='markers',
            marker=dict(symbol='diamond', color='black', size=10), name='Summary Task'
        ))

    milestone_df = df[df['is_milestone']]
    if not milestone_df.empty:
        fig.add_trace(go.Scatter(
            x=milestone_df['Start'], y=milestone_df['Task'], mode='markers',
            marker=dict(symbol='diamond', color='#f57c00', size=12), name='Milestone'
        ))

    # Add dependency arrows
    arrows = []
    task_y_mapping = {label: i for i, label in enumerate(y_axis_labels)}
    for task in project.tasks.all():
        for dep in task.successors.all():
            predecessor_row = df[df['id'] == dep.predecessor.id]
            successor_row = df[df['id'] == dep.successor.id]

            if not predecessor_row.empty and not successor_row.empty:
                arrow = go.layout.Annotation(
                    ax=predecessor_row.iloc[0]['Finish'], ay=task_y_mapping[predecessor_row.iloc[0]['Task']], axref='x', ayref='y',
                    x=successor_row.iloc[0]['Start'], y=task_y_mapping[successor_row.iloc[0]['Task']], xref='x', yref='y',
                    showarrow=True, arrowhead=2, arrowsize=1, arrowwidth=1, arrowcolor='grey'
                )
                if dep.type == 'SS':
                    arrow.ax = predecessor_row.iloc[0]['Start']
                    arrow.ay = task_y_mapping[predecessor_row.iloc[0]['Task']]
                elif dep.type == 'FF':
                    arrow.x = successor_row.iloc[0]['Finish']
                    arrow.y = task_y_mapping[successor_row.iloc[0]['Task']]
                elif dep.type == 'SF':
                    arrow.ax = predecessor_row.iloc[0]['Start']
                    arrow.ay = task_y_mapping[predecessor_row.iloc[0]['Task']]
                    arrow.x = successor_row.iloc[0]['Finish']
                    arrow.y = task_y_mapping[successor_row.iloc[0]['Task']]
                arrows.append(arrow)

    fig.update_layout(
        title_text=f'Gantt Chart: {project.name}',
        xaxis_title=None, yaxis_title=None, legend_title_text='Legend',
        barmode='overlay', annotations=arrows, plot_bgcolor='white',
        margin=dict(t=100, b=40),
        yaxis=dict(showgrid=True, gridcolor='lightgrey', categoryorder='array', categoryarray=y_axis_labels, autorange='reversed'),
        xaxis=dict(
            type='date', showgrid=True, gridcolor='lightgrey', side='top',
            minor=dict(showgrid=True, gridcolor='#f0f0f0'),
            tickformatstops=[
                dict(dtickrange=[None, 1000*60*60*24*3], value="%a %d"),
                dict(dtickrange=[1000*60*60*24*3, 1000*60*60*24*14], value="W%V"),
                dict(dtickrange=[1000*60*60*24*14, 1000*60*60*24*30*4], value="%B %Y"),
                dict(dtickrange=[1000*60*60*24*30*4, None], value="%Y")
            ],
            rangeslider=dict(visible=True)
        )
    )

    return fig.to_html(full_html=False, default_height=len(df)*35 + 200, include_plotlyjs='cdn')

